// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1 ether);
        Reverter target = new Reverter();
        vm.deal(address(c), 10 ether);
        vm.prank(address(this));
        bool ok;
        try c.sendMoney(address(target), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
